import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__vdis4gq/graph.json';
    const data = fs.readFileSync(filePath, 'utf-8');
    const graph: Graph = JSON.parse(data);

    const nodes = graph.nodes;
    const edges = graph.edges;

    // Build adjacency list (undirected graph)
    const adj: Map<string, { to: string; weight: number }[]> = new Map();
    for (const node of nodes) {
        adj.set(node, []);
    }
    for (const edge of edges) {
        if (!adj.has(edge.from)) adj.set(edge.from, []);
        if (!adj.has(edge.to)) adj.set(edge.to, []);
        adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
    }

    // Dijkstra's algorithm from node "A"
    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    for (let i = 0; i < nodes.length; i++) {
        // Find unvisited node with minimum distance
        let u: string | null = null;
        let minDist = Infinity;
        for (const node of nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                u = node;
            }
        }

        if (u === null) break;
        visited.add(u);

        // Relax all edges from u
        const neighbors = adj.get(u)!;
        for (const { to, weight } of neighbors) {
            if (!visited.has(to)) {
                const newDist = dist.get(u)! + weight;
                if (newDist < dist.get(to)!) {
                    dist.set(to, newDist);
                }
            }
        }
    }

    // Output results
    const sorted = [...nodes].sort();
    const lines: string[] = [];
    lines.push('=== Shortest Paths from A ===');
    lines.push('');
    for (const node of sorted) {
        const d = dist.get(node)!;
        lines.push(`A -> ${node}: ${d}`);
    }
    process.stdout.write(lines.join('\n') + '\n');
}

main();

