import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String os = runCommand("uname", "-s");
        String arch = runCommand("uname", "-m");
        String username = runCommand("whoami");
        String hostname = runCommand("hostname");

        String json = "{\n"
            + "  \"hostname\": \"" + escapeJson(hostname) + "\",\n"
            + "  \"os\": \"" + escapeJson(os) + "\",\n"
            + "  \"architecture\": \"" + escapeJson(arch) + "\",\n"
            + "  \"username\": \"" + escapeJson(username) + "\"\n"
            + "}";

        System.out.println(json);
    }

    private static String runCommand(String... cmd) throws Exception {
        Process process = new ProcessBuilder(cmd).start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            if (sb.length() > 0) sb.append("\n");
            sb.append(line);
        }
        reader.close();
        process.waitFor();
        return sb.toString().trim();
    }

    private static String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}

