use std::process::Command;

fn run_command(cmd: &str) -> String {
    let output = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .output()
        .expect("failed to execute command");
    let stdout = String::from_utf8_lossy(&output.stdout);
    stdout.trim().to_string()
}

fn main() {
    let hostname = run_command("hostname");
    let os = run_command("uname -s");
    let architecture = run_command("uname -m");
    let username = run_command("whoami");

    let json = format!(
        "{{\n  \"hostname\": \"{}\",\n  \"os\": \"{}\",\n  \"architecture\": \"{}\",\n  \"username\": \"{}\"\n}}",
        hostname, os, architecture, username
    );
    print!("{}", json);
