import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static class JsonParser {
        String s;
        int pos;

        JsonParser(String s) {
            this.s = s;
        }

        Object parse() {
            skipWs();
            char c = s.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            return parseNumberOrLit();
        }

        void skipWs() {
            while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++;
        }

        void expect(char c) {
            if (pos >= s.length() || s.charAt(pos) != c)
                throw new RuntimeException("Expected '" + c + "' at position " + pos);
            pos++;
        }

        Map<String, Object> parseObject() {
            Map<String, Object> m = new LinkedHashMap<>();
            expect('{');
            skipWs();
            if (s.charAt(pos) == '}') {
                pos++;
                return m;
            }
            while (true) {
                skipWs();
                String key = parseString();
                skipWs();
                expect(':');
                Object v = parse();
                m.put(key, v);
                skipWs();
                char c = s.charAt(pos);
                if (c == ',') {
                    pos++;
                } else if (c == '}') {
                    pos++;
                    break;
                } else {
                    throw new RuntimeException("Bad JSON at " + pos);
                }
            }
            return m;
        }

        List<Object> parseArray() {
            List<Object> l = new ArrayList<>();
            expect('[');
            skipWs();
            if (s.charAt(pos) == ']') {
                pos++;
                return l;
            }
            while (true) {
                l.add(parse());
                skipWs();
                char c = s.charAt(pos);
                if (c == ',') {
                    pos++;
                } else if (c == ']') {
                    pos++;
                    break;
                } else {
                    throw new RuntimeException("Bad JSON at " + pos);
                }
            }
            return l;
        }

        String parseString() {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (s.charAt(pos) != '"') {
                char c = s.charAt(pos);
                if (c == '\\') {
                    pos++;
                    char e = s.charAt(pos);
                    switch (e) {
                        case 'n': sb.append('\n'); break;
                        case 't': sb.append('\t'); break;
                        case 'r': sb.append('\r'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'u':
                            sb.append((char) Integer.parseInt(s.substring(pos + 1, pos + 5), 16));
                            pos += 4;
                            break;
                        default: sb.append(e);
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            pos++;
            return sb.toString();
        }

        Object parseNumberOrLit() {
            int start = pos;
            while (pos < s.length() && (Character.isDigit(s.charAt(pos))
                    || s.charAt(pos) == '-' || s.charAt(pos) == '+'
                    || s.charAt(pos) == '.' || s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                pos++;
            }
            String tok = s.substring(start, pos);
            if (tok.contains(".") || tok.contains("e") || tok.contains("E"))
                return Double.parseDouble(tok);
            return Long.parseLong(tok);
        }
    }

    static double num(Object o) {
        if (o instanceof Long) return ((Long) o).doubleValue();
        if (o instanceof Double) return (Double) o;
        if (o instanceof Integer) return ((Integer) o).doubleValue();
        return Double.parseDouble(o.toString());
    }

    static String fmt(double d) {
        if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 1e15)
            return Long.toString((long) d);
        return Double.toString(d);
    }

    public static void main(String[] args) throws Exception {
        String content = new String(Files.readAllBytes(
                Paths.get("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__vdis4gq/graph.json")));

