        List<String> nodes = new ArrayList<>();
        for (Object o : (List<Object>) root.get("nodes")) {
            nodes.add((String) o);
        }

        Map<String, Map<String, Double>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new HashMap<>());

        for (Object eo : (List<Object>) root.get("edges")) {
            Map<String, Object> e = (Map<String, Object>) eo;
            String from = (String) e.get("from");
            String to = (String) e.get("to");
            double w = num(e.get("weight"));
            adj.computeIfAbsent(from, k -> new HashMap<>());
            adj.computeIfAbsent(to, k -> new HashMap<>());
            // undirected: keep the minimum weight if parallel edges exist
            adj.get(from).merge(to, w, Math::min);
            adj.get(to).merge(from, w, Math::min);
        }

        // Dijkstra from "A"
        final String SRC = "A";
        Map<String, Double> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, Double.POSITIVE_INFINITY);
        dist.put(SRC, 0.0);

        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
        pq.add(new double[]{0.0, -1}); // dist, nodeIndex (use string-based instead)

        // Use a wrapper with node name
        List<String> nodeList = new ArrayList<>(nodes);
        nodeList.sort(Comparator.naturalOrder());
        Map<String, Integer> idx = new HashMap<>();
        for (int i = 0; i < nodeList.size(); i++) idx.put(nodeList.get(i), i);

        pq.clear();
        pq.add(new double[]{0.0, idx.get(SRC)});
        boolean[] visited = new boolean[nodeList.size()];

        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            double d = cur[0];
            int i = (int) cur[1];
            String u = nodeList.get(i);
            if (visited[i]) continue;
            visited[i] = true;
            if (d > dist.get(u)) continue;
            for (Map.Entry<String, Double> en : adj.getOrDefault(u, Collections.emptyMap()).entrySet()) {
                String v = en.getKey();
                double nd = d + en.getValue();
                if (nd < dist.get(v)) {
                    dist.put(v, nd);
                    pq.add(new double[]{nd, idx.get(v)});
                }
            }
        }

        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String n : nodeList) {
            System.out.println("A -> " + n + ": " + fmt(dist.get(n)));
        }
    }
