use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__vdis4gq/app.log";
    let content = fs::read_to_string(&path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..close_bracket];

        // Extract hour (positions 11-12 in "YYYY-MM-DD HH:MM:SS")
        let hour_str = &timestamp[11..13];
        let hour: u32 = hour_str.parse().expect("Invalid hour");

        let rest = line[close_bracket + 1..].trim_start();

        // Parse level (up to first space)
        let level_end = rest.find(' ').expect("No space after level");
        let level = &rest[..level_end];

        let after_level = rest[level_end..].trim_start(); // "(component) - message"

        // Parse component
        let open_paren = after_level.find('(').expect("No open paren");
        let close_paren = after_level.find(')').expect("No close paren");
        let component = &after_level[open_paren + 1..close_paren];

        // Parse message: everything after ") - "
        let after_component = &after_level[close_paren + 1..];
        let sep = after_component.find(" - ").expect("No ' - ' separator");
        let message = &after_component[sep + 3..];

        // Update counts
        *level_counts.entry(level.to_string()).or_insert(0) += 1;
        *hour_counts.entry(hour).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_comp, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(k, v)| (k.clone(), *v))
        .unwrap_or_else(|| ("N/A".to_string(), 0));
    println!("Component with Most Errors: {} ({} errors)", top_comp, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

