#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *dupstr(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

static int find_str(char **arr, int n, const char *s) {
    for (int i = 0; i < n; i++)
        if (strcmp(arr[i], s) == 0) return i;
    return -1;
}

static void process_line(char *line,
                          char ***levels, int **level_counts, int *num_levels, int *cap_levels,
                          char ***err_comps, int **err_comp_counts, int *num_ec, int *cap_ec,
                          char ***err_msgs, int *num_em, int *cap_em,
                          int hour_counts[24]) {
    /* Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message */
    if (line[0] != '[') return;

    /* Extract hour from timestamp: positions 12-13 in the line */
    if (strlen(line) < 25) return;
    int hour = (line[12] - '0') * 10 + (line[13] - '0');
    if (hour >= 0 && hour < 24) hour_counts[hour]++;

    /* Find closing bracket */
    char *close = strchr(line, ']');
    if (!close) return;
    close++;
    while (*close == ' ') close++;

    /* Extract LEVEL */
    char *level_start = close;
    char *level_end = level_start;
    while (*level_end && *level_end != ' ') level_end++;
    size_t level_len = (size_t)(level_end - level_start);
    if (level_len == 0) return;
    char level_buf[64] = {0};
    if (level_len >= sizeof(level_buf)) level_len = sizeof(level_buf) - 1;
    memcpy(level_buf, level_start, level_len);
    level_buf[level_len] = '\0';

    /* Count level */
    int li = find_str(*levels, *num_levels, level_buf);
    if (li < 0) {
        if (*num_levels == *cap_levels) {
            *cap_levels = *cap_levels ? *cap_levels * 2 : 16;
            *levels = realloc(*levels, *cap_levels * sizeof(char *));
            *level_counts = realloc(*level_counts, *cap_levels * sizeof(int));
        }
        li = *num_levels;
        (*levels)[li] = dupstr(level_buf);
        (*level_counts)[li] = 0;
        (*num_levels)++;
    }
    (*level_counts)[li]++;

    /* Extract component: expect " (component)" */
    char *comp_start = level_end;
    while (*comp_start == ' ') comp_start++;
    if (*comp_start != '(') return;
    comp_start++;
    char *comp_end = strchr(comp_start, ')');
    if (!comp_end) return;
    size_t comp_len = (size_t)(comp_end - comp_start);
    char comp_buf[256] = {0};
    if (comp_len >= sizeof(comp_buf)) comp_len = sizeof(comp_buf) - 1;
    memcpy(comp_buf, comp_start, comp_len);
    comp_buf[comp_len] = '\0';

    /* Extract message: after ") - " */
    char *msg_start = comp_end + 1;
    while (*msg_start == ' ') msg_start++;
    if (strncmp(msg_start, "- ", 2) == 0) {
        msg_start += 2;
    } else {
        /* Try single space then dash */
        if (*msg_start == '-') msg_start++;
        while (*msg_start == ' ') msg_start++;
    }

    /* If level is ERROR, track component errors and unique messages */
    if (strcmp(level_buf, "ERROR") == 0) {
        int ci = find_str(*err_comps, *num_ec, comp_buf);
        if (ci < 0) {
            if (*num_ec == *cap_ec) {
                *cap_ec = *cap_ec ? *cap_ec * 2 : 16;
                *err_comps = realloc(*err_comps, *cap_ec * sizeof(char *));
                *err_comp_counts = realloc(*err_comp_counts, *cap_ec * sizeof(int));
            }
            ci = *num_ec;
            (*err_comps)[ci] = dupstr(comp_buf);
            (*err_comp_counts)[ci] = 0;
            (*num_ec)++;
        }
        (*err_comp_counts)[ci]++;

        /* Check if message already exists */
        char *msg_copy = dupstr(msg_start);
        int mi = find_str(*err_msgs, *num_em, msg_copy);
        if (mi < 0) {
            if (*num_em == *cap_em) {
                *cap_em = *cap_em ? *cap_em * 2 : 16;
                *err_msgs = realloc(*err_msgs, *cap_em * sizeof(char *));
            }
            (*err_msgs)[*num_em] = msg_copy;
            (*num_em)++;
        } else {
            free(msg_copy);
        }
    }
}

int main(void) {
    const char *path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__vdis4gq/app.log";
    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file: %s\n", path);
        return 1;
    }

    char **levels = NULL;
    int *level_counts = NULL;
    int num_levels = 0, cap_levels = 0;

    char **err_comps = NULL;
    int *err_comp_counts = NULL;
    int num_ec = 0, cap_ec = 0;

    char **err_msgs = NULL;
    int num_em = 0, cap_em = 0;

    int hour_counts[24] = {0};

    char *line = malloc(65536);
    size_t line_cap = 65536;
    size_t line_len = 0;
    int c;

    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') {
            line[line_len] = '\0';
            process_line(line, &levels, &level_counts, &num_levels, &cap_levels,
                          &err_comps, &err_comp_counts, &num_ec, &cap_ec,
                          &err_msgs, &num_em, &cap_em, hour_counts);
            line_len = 0;
        } else {
            if (line_len + 1 >= line_cap) {
                line_cap *= 2;
                line = realloc(line, line_cap);
            }
            line[line_len++] = (char)c;
        }
    }
    if (line_len > 0) {
        line[line_len] = '\0';
        process_line(line, &levels, &level_counts, &num_levels, &cap_levels,
                      &err_comps, &err_comp_counts, &num_ec, &cap_ec,
                      &err_msgs, &num_em, &cap_em, hour_counts);
    }

    fclose(f);
    free(line);

    /* Sort levels alphabetically */
    if (num_levels > 1) {
        /* Sort both arrays together using indices */
        int *idx = malloc(num_levels * sizeof(int));
        for (int i = 0; i < num_levels; i++) idx[i] = i;
        /* Simple bubble sort on levels */
        for (int i = 0; i < num_levels - 1; i++)
            for (int j = 0; j < num_levels - 1 - i; j++)
                if (strcmp(levels[j], levels[j + 1]) > 0) {
                    char *tp = levels[j]; levels[j] = levels[j + 1]; levels[j + 1] = tp;
                    int tc = level_counts[j]; level_counts[j] = level_counts[j + 1]; level_counts[j + 1] = tc;
                }
        free(idx);
    }

    /* Sort error messages alphabetically */
    if (num_em > 1) {
        qsort(err_msgs, num_em, sizeof(char *), cmp_str);
    }

    /* Find component with most errors */
    int best_ci = -1;
    int best_count = 0;
    for (int i = 0; i < num_ec; i++) {
        if (err_comp_counts[i] > best_count ||
            (err_comp_counts[i] == best_count && best_ci >= 0 &&
             strcmp(err_comps[i], err_comps[best_ci]) < 0)) {
            best_count = err_comp_counts[i];
            best_ci = i;
        }
    }

    /* Find busiest hour */
    int best_hour = 0;
    int best_hcount = hour_counts[0];
    for (int i = 1; i < 24; i++) {
        if (hour_counts[i] > best_hcount) {
            best_hcount = hour_counts[i];
            best_hour = i;
        }
    }

    /* Output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < num_levels; i++) {
        printf("  %s: %d\n", levels[i], level_counts[i]);
    }
    printf("\n");
    if (best_ci >= 0) {
        printf("Component with Most Errors: %s (%d errors)\n", err_comps[best_ci], best_count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < num_em; i++) {
        printf("  - %s\n", err_msgs[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_hour, best_hcount);

    /* Cleanup */
    for (int i = 0; i < num_levels; i++) free(levels[i]);
    free(levels);
    free(level_counts);
    for (int i = 0; i < num_ec; i++) free(err_comps[i]);
    free(err_comps);
    free(err_comp_counts);
    for (int i = 0; i < num_em; i++) free(err_msgs[i]);
    free(err_msgs);

