#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *dupstr(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}

static int find_str(char **arr, int n, const char *s) {
    for (int i = 0; i < n; i++)
        if (strcmp(arr[i], s) == 0) return i;
    return -1;
}

static void process_line(char *line,
                          char ***levels, int **level_counts, int *num_levels, int *cap_levels,
                          char ***err_comps, int **err_comp_counts, int *num_ec, int *cap_ec,
                          char ***err_msgs, int *num_em, int *cap_em,
                          int hour_counts[24]) {
    /* Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message */
    if (line[0] != '[') return;

    /* Extract hour from timestamp: positions 12-13 in the line */
    if (strlen(line) < 25) return;
    int hour = (line[12] - '0') * 10 + (line[13] - '0');
    if (hour >= 0 && hour < 24) hour_counts[hour]++;

    /* Find closing bracket */
    char *close = strchr(line, ']');
    if (!close) return;
    close++;
    while (*close == ' ') close++;

    /* Extract LEVEL */
    char *level_start = close;
    char *level_end = level_start;
    while (*level_end && *level_end != ' ') level_end++;
    size_t level_len = (size_t)(level_end - level_start);
    if (level_len == 0) return;
    char level_buf[64] = {0};
    if (level_len >= sizeof(level_buf)) level_len = sizeof(level_buf) - 1;
    memcpy(level_buf, level_start, level_len);
    level_buf[level_len] = '\0';

    /* Count level */
    int li = find_str(*levels, *num_levels, level_buf);
    if (li < 0) {
        if (*num_levels == *cap_levels) {
            *cap_levels = *cap_levels ? *cap_levels * 2 : 16;
            *levels = realloc(*levels, *cap_levels * sizeof(char *));
            *level_counts = realloc(*level_counts, *cap_levels * sizeof(int));
        }
        li = *num_levels;
        (*levels)[li] = dupstr(level_buf);
        (*level_counts)[li] = 0;
        (*num_levels)++;
    }
    (*level_counts)[li]++;

    /* Extract component: expect " (component)" */
    char *comp_start = level_end;
    while (*comp_start == ' ') comp_start++;
    if (*comp_start != '(') return;
    comp_start++;
    char *comp_end = strchr(comp_start, ')');
    if (!comp_end) return;
    size_t comp_len = (size_t)(comp_end - comp_start);
    char comp_buf[256] = {0};
    if (comp_len >= sizeof(comp_buf)) comp_len = sizeof(comp_buf) - 1;
    memcpy(comp_buf, comp_start, comp_len);
    comp_buf[comp_len] = '\0';

    /* Extract message: after ") - " */
    char *msg_start = comp_end + 1;
    while (*msg_start == ' ') msg_start++;
    if (strncmp(msg_start, "- ", 2) == 0) {
        msg_start += 2;
    } else {
        /* Try single space then dash */
        if (*msg_start == '-') msg_start++;
        while (*msg_start == ' ') msg_start++;
    }

    /* If level is ERROR, track component errors and unique messages */
    if (strcmp(level_buf, "ERROR") == 0) {
        int ci = find_str(*err_comps, *num_ec, comp_buf);
        if (ci < 0) {
            if (*num_ec == *cap_ec) {
                *cap_ec = *cap_ec ? *cap_ec * 2 : 16;
                *err_comps = realloc(*err_comps, *cap_ec * sizeof(char *));
                *err_comp_counts = realloc(*err_comp_counts, *cap_ec * sizeof(int));
            }
            ci = *num_ec;
            (*err_comps)[ci] = dupstr(comp_buf);
            (*err_comp_counts)[ci] = 0;
            (*num_ec)++;
        }
        (*err_comp_counts)[ci]++;

        /* Check if message already exists */
        char *msg_copy = dupstr(msg_start);
        int mi = find_str(*err_msgs, *num_em, msg_copy);
        if (mi < 0) {
            if (*num_em == *cap_em) {
                *cap_em = *cap_em ? *cap_em * 2 : 16;
                *err_msgs = realloc(*err_msgs, *cap_em * sizeof(char *));
            }
            (*err_msgs)[*num_em] = msg_copy;
            (*num_em)++;
        } else {
            free(msg_copy);
        }
    }
}

