import * as fs from 'fs';
import * as path from 'path';

const ROOT = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__vdis4gq/project_tree';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  let newlines = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 10) newlines++;
  }
  if (content[content.length - 1] !== 10) newlines++;
  return newlines;
}

function walkDir(dir: string, root: string): Map<string, FileStats[]> {
  const result = new Map<string, FileStats[]>();

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return result;
  }

  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;

    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      const sub = walkDir(fullPath, root);
      for (const [ext, files] of sub) {
        if (!result.has(ext)) result.set(ext, []);
        result.get(ext)!.push(...files);
      }
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      const content = fs.readFileSync(fullPath);
      const lines = countLines(content);
      const chars = content.length;
      const ext = path.extname(entry.name);

      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }

  return result;
}

function main(): void {
  const allFiles = walkDir(ROOT, ROOT);
  const extensions = [...allFiles.keys()].sort();

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  const output: string[] = [];
  output.push('=== File Tree Analysis ===');
  output.push('');

  for (const ext of extensions) {
    const files = allFiles.get(ext)!.sort((a, b) =>
      a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0
    );

    const extFileCount = files.length;
    const extLines = files.reduce((s, f) => s + f.lines, 0);
    const extChars = files.reduce((s, f) => s + f.chars, 0);

    totalFiles += extFileCount;
    totalLines += extLines;
    totalChars += extChars;

    output.push(`Extension: ${ext}`);
    output.push(`  Files: ${extFileCount}`);
    output.push(`  Total Lines: ${extLines}`);
    output.push(`  Total Characters: ${extChars}`);
    for (const f of files) {
      output.push(`    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars`);
    }
  }

  output.push('');
  output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

  process.stdout.write(output.join('\n') + '\n');
}

main();

