struct FileStats {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var allFiles: [String: [FileStats]] = [:]

func walkDirectory(_ dirPath: String, relativeTo: String) {
    guard let contents = try? fm.contentsOfDirectory(atPath: dirPath) else { return }

    for name in contents {
        let fullPath = dirPath + "/" + name
        let relativePath = relativeTo.isEmpty ? name : relativeTo + "/" + name

        let attrs = try? fm.attributesOfItem(atPath: fullPath)
        let fileType = attrs?[.type] as? String

        if fileType == "NSFileTypeSymbolicLink" {
            continue
        }

        if fileType == "NSFileTypeDirectory" {
            walkDirectory(fullPath, relativeTo: relativePath)
        } else if fileType == "NSFileTypeRegular" {
            let data = (try? Data(contentsOf: URL(fileURLWithPath: fullPath))) ?? Data()
            let chars = data.count

            let lines: Int
            if data.isEmpty {
                lines = 0
            } else {
                var lineCount = 0
                for byte in data {
                    if byte == 10 {
                        lineCount += 1
                    }
                }
                if data.last != 10 {
                    lineCount += 1
                }
                lines = lineCount
            }

            let ext = (name as NSString).pathExtension
            let extStr = "." + ext

            let stats = FileStats(relativePath: relativePath, lines: lines, chars: chars)

            if allFiles[extStr] == nil {
                allFiles[extStr] = []
            }
            allFiles[extStr]!.append(stats)
        }
    }
