            for (byte b : bytes) {
                if (b == '\n') lineCount++;
            }
            if (bytes[bytes.length - 1] != '\n') lineCount++;
        }

        extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new String[]{relPath, String.valueOf(lineCount), String.valueOf(charCount)});
