                if (Files.isSymbolicLink(entry)) continue;
                if (Files.isDirectory(entry)) {
                    walk(entry);
                } else if (Files.isRegularFile(entry)) {
                    processFile(entry);
                }
            }
        }
    }

    static void processFile(Path file) throws IOException {
        String relPath = root.relativize(file.toAbsolutePath().normalize()).toString().replace(File.separatorChar, '/');

        String fileName = file.getFileName().toString();
        int lastDot = fileName.lastIndexOf('.');
        String ext;
        if (lastDot > 0) {
            ext = fileName.substring(lastDot);
        } else {
            ext = "(no extension)";
        }

        byte[] bytes = Files.readAllBytes(file);
        long charCount = bytes.length;

        long lineCount = 0;
        if (bytes.length > 0) {
            for (byte b : bytes) {
                if (b == '\n') lineCount++;
            }
            if (bytes[bytes.length - 1] != '\n') lineCount++;
        }

        extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new String[]{relPath, String.valueOf(lineCount), String.valueOf(charCount)});
    }
}
