    if n == n.floor() && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1__vdis4gq/graph.json";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");
    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let nodes_json = json.get("nodes").expect("missing nodes");
    let edges_json = json.get("edges").expect("missing edges");

    let nodes: Vec<String> = nodes_json
        .as_arr()
        .expect("nodes not array")
        .iter()
        .map(|n| n.as_str().expect("node not string").to_string())
        .collect();

    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).insert(Vec::new());
    }

    let edges_arr = edges_json.as_arr().expect("edges not array");
    for e in edges_arr {
        let from = e.get("from").expect("missing from").as_str().expect("from not str").to_string();
        let to = e.get("to").expect("missing to").as_str().expect("to not str").to_string();
        let weight = e.get("weight").expect("missing weight").as_f64().expect("weight not num");
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), weight));
        adj.entry(to).or_insert_with(Vec::new).push((from, weight));
    }

    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
    heap.push(HeapItem {
        dist: 0.0,
        node: source.clone(),
    });

    while let Some(HeapItem { dist: d, node }) = heap.pop() {
        if d > *dist.get(&node).unwrap_or(&f64::INFINITY) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, w) in neighbors {
                let new_dist = d + w;
                if new_dist < *dist.get(neighbor).unwrap_or(&f64::INFINITY) {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(HeapItem {
                        dist: new_dist,
                        node: neighbor.clone(),
                    });
                }
            }
        }
    }

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    print!("=== Shortest Paths from A ===\n");
    print!("\n");
    for node in &sorted_nodes {
        let d = dist.get(node).unwrap_or(&f64::INFINITY);
        if *d == f64::INFINITY {
