            return a->bool_val == b->bool_val;
        case JSON_NUMBER:
            return a->num_val == b->num_val;
        case JSON_STRING:
            return strcmp(a->string_val, b->string_val) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++) {
