static JsonValue *deep_merge(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = new_object();
        for (int i = 0; i < a->pair_count; i++) {
            int found = -1;
            for (int j = 0; j < b->pair_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    found = j;
                    break;
                }
            }
            if (found >= 0) {
                JsonValue *merged = deep_merge(a->values[i], b->values[found]);
                add_pair(result, a->keys[i], merged);
            } else {
                add_pair(result, a->keys[i], a->values[i]);
            }
        }
        for (int j = 0; j < b->pair_count; j++) {
            int found = -1;
            for (int i = 0; i < a->pair_count; i++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    found = i;
                    break;
                }
            }
            if (found < 0) {
                add_pair(result, b->keys[j], b->values[j]);
            }
        }
        return result;
    } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = new_array();
        for (int i = 0; i < a->item_count; i++) {
            add_item(result, a->items[i]);
        }
        for (int i = 0; i < b->item_count; i++) {
            int dup = 0;
            for (int j = 0; j < result->item_count; j++) {
                if (json_equal(result->items[j], b->items[i])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                add_item(result, b->items[i]);
            }
        }
