            fputs(v->bool_val ? "true" : "false", stdout);
            break;
        case JSON_NUMBER:
            fputs(v->num_raw, stdout);
            break;
        case JSON_STRING:
            print_escaped_string(v->string_val);
            break;
        case JSON_ARRAY: {
            if (v->item_count == 0) {
                fputs("[]", stdout);
                return;
            }
            fputc('[', stdout);
            for (int i = 0; i < v->item_count; i++) {
                fputc('\n', stdout);
                print_indent(indent + 1);
                print_json(v->items[i], indent + 1);
                if (i < v->item_count - 1) fputc(',', stdout);
            }
            fputc('\n', stdout);
            print_indent(indent);
            fputc(']', stdout);
            break;
        }
        case JSON_OBJECT: {
            if (v->pair_count == 0) {
                fputs("{}", stdout);
                return;
            }
            int *idx = (int *)malloc(v->pair_count * sizeof(int));
            for (int i = 0; i < v->pair_count; i++) idx[i] = i;
            g_sort_keys = v->keys;
            qsort(idx, v->pair_count, sizeof(int), cmp_keys);
