                fputs(": ", stdout);
                print_json(v->values[idx[i]], indent + 1);
                if (i < v->pair_count - 1) fputc(',', stdout);
            }
            fputc('\n', stdout);
            print_indent(indent);
            fputc('}', stdout);
            free(idx);
            break;
        }
    }
}

